class Gradebook:
    def __init__(self) -> None:
        # assignment name -> (weight, kind)
        self._assignments: dict[str, tuple[float, str]] = {}
        # student name -> {assignment name -> grade}
        self._grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError(f"Invalid assignment kind: {kind!r}")
        if name in self._assignments:
            raise ValueError(f"Assignment already exists: {name!r}")
        self._assignments[name] = (float(weight), kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the scale 2.0-5.0")
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment!r}")
        self._grades.setdefault(student, {})[assignment] = float(grade)

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})

        # Determine lowest quiz grade (only if more than one quiz is recorded)
        quiz_grades = [
            student_grades[name]
            for name, (_, kind) in self._assignments.items()
            if kind == "quiz" and name in student_grades
        ]
        dropped_quiz = min(quiz_grades) if len(quiz_grades) > 1 else None

        total_weight = 0.0
        weighted_sum = 0.0
        quiz_dropped_already = False

        for name, (weight, kind) in self._assignments.items():
            grade = student_grades.get(name, 2.0)
            if (
                kind == "quiz"
                and dropped_quiz is not None
                and not quiz_dropped_already
                and name in student_grades
                and grade == dropped_quiz
            ):
                # Drop this quiz's contribution
                quiz_dropped_already = True
                continue
            weighted_sum += weight * grade
            total_weight += weight

        if total_weight == 0:
            return 0.0
        return round(weighted_sum / total_weight, 2)
